{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 관리 금연공원 흡연 적발 시 과태료 금액",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시가 관리하는 금연공원에서 담배를 피우다 적발되면 10만원의 과태료가 부과된다. 조례 제10조제1항은 시장이 제5조제4항을 위반하여 금연구역에서 흡연한 사람에게 10만원의 과태료를 부과·징수한다고 정하고 있다.",
          "b_ids": "금연:제10조제1항, 금연:제5조제4항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울시 관리 금연공원 관리 부서의 과태료 부과 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "해당 공원을 관리하는 서울특별시 보조기관 및 사업소장은 과태료를 부과·징수할 수 있다. 조례 제11조는 시장이 도시공원을 금연구역으로 지정할 때 과태료의 부과·징수 사무를 「서울특별시 도시공원 조례」에 따라 해당 공원을 관리하는 서울특별시 보조기관 및 사업소장에게 위임한다고 정하고 있다.",
          "b_ids": "금연:제11조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
